import { execFileSync } from "node:child_process";
import { EventEmitter } from "node:events";
import net from "node:net";
import path from "node:path";
import { pathToFileURL } from "node:url";

const repoPath = process.argv[2];
if (!repoPath) {
  throw new Error("usage: proof-live.mjs <repo-path>");
}
const headSha = execFileSync("git", ["rev-parse", "HEAD"], {
  cwd: repoPath,
  encoding: "utf8",
}).trim();

const { inspectPortUsage } = await import(
  pathToFileURL(path.join(repoPath, "src/infra/ports-inspect.ts")).href
);

class DelayedRefusalSocket extends EventEmitter {
  timeoutTimer;
  refusalTimer;
  closed = false;

  setTimeout(timeoutMs, callback) {
    clearTimeout(this.timeoutTimer);
    this.timeoutTimer = setTimeout(() => callback?.call(this), timeoutMs);
    return this;
  }

  destroy(error) {
    if (this.closed) {
      return this;
    }
    this.closed = true;
    clearTimeout(this.timeoutTimer);
    clearTimeout(this.refusalTimer);
    if (error) {
      this.emit("error", error);
    }
    queueMicrotask(() => this.emit("close"));
    return this;
  }
}

async function allocateClosedPort(host) {
  const server = net.createServer();
  await new Promise((resolve, reject) => {
    server.once("error", reject);
    server.listen({ host, port: 0 }, resolve);
  });
  const address = server.address();
  if (!address || typeof address === "string") {
    throw new Error("expected an ephemeral TCP address");
  }
  await new Promise((resolve, reject) =>
    server.close((error) => (error ? reject(error) : resolve())),
  );
  return address.port;
}

const host = "127.0.0.1";
const port = await allocateClosedPort(host);
const originalDescriptor = Object.getOwnPropertyDescriptor(net, "connect");
Object.defineProperty(net, "connect", {
  configurable: true,
  writable: true,
  value: () => {
    const socket = new DelayedRefusalSocket();
    socket.refusalTimer = setTimeout(() => {
      const error = Object.assign(new Error("connect ECONNREFUSED"), { code: "ECONNREFUSED" });
      socket.destroy(error);
    }, 400);
    return socket;
  },
});
let delayedRefusal;
try {
  delayedRefusal = (
    await inspectPortUsage(port, { probeHosts: [host] }, Date.now() + 1_000)
  ).status;
} finally {
  if (originalDescriptor) {
    Object.defineProperty(net, "connect", originalDescriptor);
  }
}

const listener = net.createServer();
await new Promise((resolve, reject) => {
  listener.once("error", reject);
  listener.listen({ host, port: 0 }, resolve);
});
const listenerAddress = listener.address();
if (!listenerAddress || typeof listenerAddress === "string") {
  throw new Error("expected a live TCP listener address");
}
let busyControl;
try {
  busyControl = (
    await inspectPortUsage(listenerAddress.port, { probeHosts: [host] }, Date.now() + 1_000)
  ).status;
} finally {
  await new Promise((resolve, reject) =>
    listener.close((error) => (error ? reject(error) : resolve())),
  );
}

console.log(
  JSON.stringify({
    headSha,
    entrypoint: "inspectPortUsage -> probePortUsage -> probeTcpListener",
    boundary: "real loopback bind with delayed ECONNREFUSED at net.connect",
    delayedRefusalMs: 400,
    requestedDeadlineMs: 1_000,
    delayedRefusal,
    busyControl,
  }),
);
```

