```ts
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import net from 'node:net';
import path from 'node:path';
import { inspectPortUsage } from '../../src/infra/ports-inspect.js';
import { waitForGatewayPortRelease } from '../../src/daemon/schtasks-port-diagnostics.js';

const configPath = path.join(process.env.OPENCLAW_STATE_DIR!, 'openclaw.json');
process.env.OPENCLAW_CONFIG_PATH = configPath;
await fs.mkdir(path.dirname(configPath), { recursive: true });
await fs.writeFile(configPath, JSON.stringify({
  gateway: { mode: 'local', bind: 'loopback', auth: { mode: 'none' }, controlUi: { enabled: false } },
  agents: { entries: { main: {} } },
}));
const reservation = net.createServer();
await new Promise<void>((resolve) => reservation.listen(0, '127.0.0.1', resolve));
const address = reservation.address();
assert(address && typeof address !== 'string');
await new Promise<void>((resolve) => reservation.close(() => resolve()));
const { startGatewayServer } = await import('../../src/gateway/server.js');
const gateway = await startGatewayServer(address.port, {
  bind: 'loopback', auth: { mode: 'none' }, controlUiEnabled: false, sidecarStartup: 'defer',
});
try {
  assert.equal((await inspectPortUsage(address.port, { probeHosts: ['127.0.0.1'] })).status, 'busy');
  console.log('isolated production macOS Gateway: listening, native inspection=busy');
} finally {
  await gateway.close({ reason: 'isolated stop-settlement proof' });
}
const started = performance.now();
assert.equal(await waitForGatewayPortRelease(address.port, ['127.0.0.1']), true);
console.log(`production Gateway teardown positively confirmed free in ${Math.round(performance.now()-started)} ms`);
